export function getHeroSkillTreeTheme(heroId = 'mage') {
  if (HERO_SKILL_TREE_THEMES[heroId]) return HERO_SKILL_TREE_THEMES[heroId];
  if (heroId?.endsWith('_ex')) {
    const baseKey = heroId.slice(0, -3);
    if (HERO_SKILL_TREE_THEMES[baseKey]) return HERO_SKILL_TREE_THEMES[baseKey];
  }
  return HERO_SKILL_TREE_THEMES.mage;
}

export const ADVENTURE_HERO_PROGRESS_STORAGE_KEY = 'avs_adv_hero_progress_v1';
export const ADVENTURE_KEEP_LEVEL_STORAGE_KEY = 'avs_adv_keep_level_v1';

export function normalizeAdventureProgressMode(rawMode) {
  return String(rawMode || '').trim().toLowerCase() === 'keep' ? 'keep' : 'fresh';
}

function resolveProgressStorage(storageOverride = null) {
  if (storageOverride) return storageOverride;
  try {
    if (typeof window !== 'undefined' && window && window.localStorage) {
      return window.localStorage;
    }
  } catch {
    return null;
  }
  return null;
}

export function loadAdventureProgressMode(storageOverride = null) {
  const store = resolveProgressStorage(storageOverride);
  if (!store || typeof store.getItem !== 'function') return 'fresh';
  try {
    return normalizeAdventureProgressMode(store.getItem(ADVENTURE_KEEP_LEVEL_STORAGE_KEY));
  } catch {
    return 'fresh';
  }
}

export function saveAdventureProgressMode(mode, storageOverride = null) {
  const clean = normalizeAdventureProgressMode(mode);
  const store = resolveProgressStorage(storageOverride);
  if (store && typeof store.setItem === 'function') {
    try {
      store.setItem(ADVENTURE_KEEP_LEVEL_STORAGE_KEY, clean);
    } catch {
      // Ignore storage quota or sandbox errors safely
    }
  }
  return clean;
}

function sanitizeHeroProgressRecord(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const maxLevel = 10;
  const level = Number.isFinite(raw.level)
    ? Math.max(1, Math.min(maxLevel, Math.floor(raw.level)))
    : 1;
  const expectedXpToNext = Math.round(115 * Math.pow(1.32, level - 1));
  const xpToNext =
    Number.isFinite(raw.xpToNext) && raw.xpToNext > 0
      ? Math.round(raw.xpToNext)
      : expectedXpToNext;
  const xp =
    level >= maxLevel
      ? 0
      : Number.isFinite(raw.xp)
        ? Math.max(0, Math.min(Math.max(0, xpToNext - 1), Math.round(raw.xp)))
        : 0;

  const ranks = {};
  let spent = 0;
  const rawRanks = raw.ranks && typeof raw.ranks === 'object' ? raw.ranks : {};
  for (const node of ADVENTURE_SKILL_TREE) {
    const r = Number.isFinite(rawRanks[node.id])
      ? Math.max(0, Math.min(node.maxRank, Math.floor(rawRanks[node.id])))
      : 0;
    ranks[node.id] = r;
    spent += r;
  }

  // Enforce tier unlock invariants and total SP budget (`totalSpEarned === level`)
  if (spent > level) {
    for (const node of ADVENTURE_SKILL_TREE) {
      ranks[node.id] = 0;
    }
    spent = 0;
  } else {
    for (const branch of ['wrath', 'astral', 'aegis']) {
      const t1 = ADVENTURE_SKILL_TREE.find((n) => n.branch === branch && n.tier === 1);
      const t2 = ADVENTURE_SKILL_TREE.find((n) => n.branch === branch && n.tier === 2);
      const t3 = ADVENTURE_SKILL_TREE.find((n) => n.branch === branch && n.tier === 3);
      if (t1 && t2 && ranks[t1.id] < 1 && ranks[t2.id] > 0) {
        spent -= ranks[t2.id];
        ranks[t2.id] = 0;
      }
      if (t1 && t2 && t3 && ranks[t1.id] + ranks[t2.id] < 2 && ranks[t3.id] > 0) {
        spent -= ranks[t3.id];
        ranks[t3.id] = 0;
      }
    }
  }

  const maxUnspent = Math.max(0, level - spent);
  const skillPoints = Number.isFinite(raw.skillPoints)
    ? Math.max(0, Math.min(maxUnspent, Math.floor(raw.skillPoints)))
    : maxUnspent;

  return {
    level,
    xp,
    xpToNext,
    skillPoints: spent + skillPoints === level ? skillPoints : maxUnspent,
    ranks
  };
}

export function loadAllAdventureHeroProgress(storageOverride = null) {
  const store = resolveProgressStorage(storageOverride);
  if (!store || typeof store.getItem !== 'function') return {};
  try {
    const raw = store.getItem(ADVENTURE_HERO_PROGRESS_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    const out = {};
    for (const [heroId, rec] of Object.entries(parsed)) {
      if (!heroId || typeof heroId !== 'string') continue;
      const clean = sanitizeHeroProgressRecord(rec);
      if (clean) out[heroId] = clean;
    }
    return out;
  } catch {
    return {};
  }
}

export function loadAdventureHeroProgress(heroId, storageOverride = null) {
  if (!heroId || typeof heroId !== 'string') return null;
  const cleanHero = heroId.trim();
  if (!cleanHero) return null;
  const all = loadAllAdventureHeroProgress(storageOverride);
  return all[cleanHero] || null;
}

export function saveAdventureHeroProgress(heroId, snapshot, storageOverride = null) {
  if (!heroId || typeof heroId !== 'string') return null;
  const cleanHero = heroId.trim();
  if (!cleanHero) return null;
  const cleanRec = sanitizeHeroProgressRecord(snapshot);
  if (!cleanRec) return null;
  const all = loadAllAdventureHeroProgress(storageOverride);
  all[cleanHero] = cleanRec;
  const store = resolveProgressStorage(storageOverride);
  if (store && typeof store.setItem === 'function') {
    try {
      store.setItem(ADVENTURE_HERO_PROGRESS_STORAGE_KEY, JSON.stringify(all));
    } catch {
      // Ignore storage quota or sandbox errors safely
    }
  }
  return cleanRec;
}

export function resetAdventureHeroProgress(heroId, storageOverride = null) {
  if (!heroId || typeof heroId !== 'string') return false;
  const cleanHero = heroId.trim();
  if (!cleanHero) return false;
  const all = loadAllAdventureHeroProgress(storageOverride);
  const existed = Object.prototype.hasOwnProperty.call(all, cleanHero);
  delete all[cleanHero];
  const store = resolveProgressStorage(storageOverride);
  if (store && typeof store.setItem === 'function') {
    try {
      store.setItem(ADVENTURE_HERO_PROGRESS_STORAGE_KEY, JSON.stringify(all));
    } catch {
      // Ignore storage quota or sandbox errors safely
    }
  }
  return existed;
}

export class AdventureProgression {
  constructor(adventure) {
    this.adventure = adventure;
    this.resetForNewCampaign();
  }

  resetForNewCampaign() {
    this.level = 1;
    this.maxLevel = 10;
    this.xp = 0;
    this.xpToNext = 115;

    // Start with 1 Skill Point at Lv.1 so players can customize their Adventure build immediately!
    this.skillPoints = 1;
    this.totalSpEarned = 1;

    this.ranks = {};
    for (const node of ADVENTURE_SKILL_TREE) {
      this.ranks[node.id] = 0;
    }

    // Dedicated Adventure Combat Resources (completely decoupled from VS PvP gauges!)
    this.spirit = 68;
    this.maxSpirit = 100;
    this.ultCharge = 0; // 0..100 (Solar Awakening — Ultimate)
    this.astralCharge = 0; // 0..100 (Astral Relic Seals — Super-Ultimate)

    this.comboHits = 0;
    this.comboTimer = 0;
    this.seekerShotCounter = 0;
    this._skillCdShaveThrottle = 0;
  }

  exportProgressSnapshot() {
    const ranksCopy = {};
    for (const node of ADVENTURE_SKILL_TREE) {
      ranksCopy[node.id] = this.ranks[node.id] || 0;
    }
    return {
      level: this.level,
      xp: this.xp,
      xpToNext: this.xpToNext,
      skillPoints: this.skillPoints,
      ranks: ranksCopy
    };
  }

  importProgressSnapshot(snapshot, player = null, fullHeal = true) {
    const clean = sanitizeHeroProgressRecord(snapshot);
    if (!clean) return false;
    this.resetForNewCampaign();
    this.level = clean.level;
    this.xp = clean.xp;
    this.xpToNext = clean.xpToNext;
    this.skillPoints = clean.skillPoints;
    this.totalSpEarned = clean.level;
    for (const node of ADVENTURE_SKILL_TREE) {
      this.ranks[node.id] = clean.ranks[node.id] || 0;
    }
    if (player) {
      const stats = this.getComputedStats();
      player.maxHp = stats.maxHp;
      player.hp = fullHeal ? stats.maxHp : Math.min(player.hp, stats.maxHp);
      this.syncGaugesToPlayer(player);
    }
    return true;
  }

  saveToStorage(heroId, storageOverride = null) {
    return saveAdventureHeroProgress(heroId, this.exportProgressSnapshot(), storageOverride);
  }

  loadFromStorage(heroId, player = null, storageOverride = null) {
    const rec = loadAdventureHeroProgress(heroId, storageOverride);
    if (!rec) return false;
    return this.importProgressSnapshot(rec, player, true);
  }

  resetChampionToLv1(heroId, player = null, storageOverride = null) {
    this.resetForNewCampaign();
    if (heroId) {
      resetAdventureHeroProgress(heroId, storageOverride);
    }
    if (player) {
      const stats = this.getComputedStats();
      player.maxHp = stats.maxHp;
      if (!player.isDead) {
        player.hp = Math.min(player.hp, stats.maxHp);
      }
      this.syncGaugesToPlayer(player);
    }
    return true;
  }

  getRank(nodeId) {
    return this.ranks[nodeId] || 0;
  }

  getBranchPointsSpent(branch) {
    let sum = 0;
    for (const node of ADVENTURE_SKILL_TREE) {
      if (node.branch === branch) {
        sum += this.ranks[node.id] || 0;
      }
    }
    return sum;
  }

  canUpgradeNode(nodeId) {
    const node = ADVENTURE_SKILL_TREE.find((n) => n.id === nodeId);
    if (!node) return false;
    const cur = this.getRank(nodeId);
    if (cur >= node.maxRank || this.skillPoints <= 0) return false;
    const branchSpent = this.getBranchPointsSpent(node.branch);
    if (node.tier === 2 && branchSpent < 1) return false;
    if (node.tier === 3 && branchSpent < 2) return false;
    return true;
  }

  upgradeNode(nodeId, player = null) {
    if (!this.canUpgradeNode(nodeId)) return false;
    const prevMaxHp = this.getComputedStats().maxHp;
    this.ranks[nodeId] = (this.ranks[nodeId] || 0) + 1;
    this.skillPoints = Math.max(0, this.skillPoints - 1);

    if (nodeId === 'astral_3') {
      this.gainAstralRelic(18, player, 'ASTRAL SEAL UNLOCKED!');
    }

    if (player) {
      this.applyStatsToFighter(player, prevMaxHp);
      this.syncGaugesToPlayer(player);
    }
    this.adventure?.persistHeroProgressIfEnabled?.();
    return true;
  }

  refundAllSkillPoints(player = null) {
    let spent = 0;
    for (const node of ADVENTURE_SKILL_TREE) {
      spent += this.ranks[node.id] || 0;
      this.ranks[node.id] = 0;
    }
    if (spent <= 0) return false;
    this.skillPoints += spent;
    // Clamp Astral Charge if Cataclysm Sovereign bonus was refunded before being spent
    this.astralCharge = Math.min(this.astralCharge, 100);
    if (player) {
      const stats = this.getComputedStats();
      player.maxHp = stats.maxHp;
      player.hp = Math.min(player.hp, player.maxHp);
      this.syncGaugesToPlayer(player);
    }
    this.adventure?.persistHeroProgressIfEnabled?.();
    return true;
  }

  getComputedStats() {
    const lv = Math.max(1, this.level);
    const rWrath1 = this.getRank('wrath_1');
    const rWrath2 = this.getRank('wrath_2');
    const rWrath3 = this.getRank('wrath_3');
    const rAstral1 = this.getRank('astral_1');
    const rAstral2 = this.getRank('astral_2');
    const rAstral3 = this.getRank('astral_3');
    const rAegis1 = this.getRank('aegis_1');
    const rAegis2 = this.getRank('aegis_2');
    const rAegis3 = this.getRank('aegis_3');

    const hasOverdriveSurge = Boolean(this.adventure?.hasRelic?.('overdrive_surge'));
    const hasHasteActive = Boolean(
      this.adventure?.hasRelic?.('haste_momentum') &&
        (this.adventure?._relicHasteTimer || 0) > 0
    );

    const maxHp = 1320 + (lv - 1) * 115 + rAegis1 * 240;
    const atkMult = 0.64 + (lv - 1) * 0.045 + rWrath1 * 0.15;
    const skillMult = 0.74 + (lv - 1) * 0.045 + rWrath1 * 0.08 + rWrath3 * 0.28;
    const ultMult = (0.50 + (lv - 1) * 0.04 + rAstral2 * 0.28) * (hasOverdriveSurge ? 1.22 : 1.0);
    const superUltMult = (0.45 + (lv - 1) * 0.04 + rAstral3 * 0.35) * (hasOverdriveSurge ? 1.22 : 1.0);

    const skillSpiritCost = rWrath3 >= 2 ? 26 : rWrath3 === 1 ? 32 : 38;
    const basicSpiritGain = 8 + rWrath2 * 3;
    const basicSkillCdShave = 0.10 + rWrath2 * 0.12;

    const ultGainMult = (1.0 + rAstral1 * 0.25) * (hasOverdriveSurge ? 1.30 : 1.0);
    const bossHitUltGain = rAstral1 > 0 ? 0.5 + rAstral1 * 1.4 : 0.45;
    const ultResonanceAstral = 18 + rAstral2 * 14;

    const wardReduction = Math.min(0.42, 0.04 + (lv - 1) * 0.015 + rAegis1 * 0.07);
    const moveSpeedMult = (1.0 + rAegis2 * 0.12) * (hasHasteActive ? 1.16 : 1.0);
    const mobilityCdMult = Math.max(
      0.42,
      Math.max(0.52, 1.0 - rAegis2 * 0.20) * (hasHasteActive ? 0.80 : 1.0)
    );
    const skillCdMult = hasHasteActive ? 0.80 : 1.0;
    const evasiveHealBonus = rAegis3 * 18;
    const emberHealPct = 0;
    const evasiveSpiritBonus = rAegis3 * 4;

    return {
      maxHp,
      atkMult,
      skillMult,
      ultMult,
      superUltMult,
      skillSpiritCost,
      basicSpiritGain,
      basicSkillCdShave,
      ultGainMult,
      bossHitUltGain,
      ultResonanceAstral,
      wardReduction,
      moveSpeedMult,
      mobilityCdMult,
      skillCdMult,
      evasiveHealBonus,
      emberHealPct,
      evasiveSpiritBonus,
      hasHomingSeeker: rWrath1 >= 2
    };
  }

  attachToFighter(player) {
    if (!player) return;
    if (!player._advOrig) {
      player._advOrig = {
        maxHp: player.maxHp,
        hp: player.hp,
        gainMana: player.gainMana.bind(player),
        gainFinisher: player.gainFinisher.bind(player),
        takeDamage: player.takeDamage.bind(player),
        heal: player.heal.bind(player)
      };
    }

    const stats = this.getComputedStats();
    player.maxHp = stats.maxHp;
    player.hp = stats.maxHp;
    player.mana = 0;
    player.finisherGauge = 0;

    // Intercept VS passive Mana & Finisher gains so Adventure Mode uses ONLY Soul Embers, Combos & Astral Relics!
    player.gainMana = () => {};
    player.gainFinisher = () => {};

    // Wrap Adventure Healing so flat PvP micro-heals scale naturally to Adventure HP + Undying Phoenix bonuses!
    player.heal = (amount, label = '') => {
      if (player.isDead || amount <= 0) return 0;
      const curStats = this.getComputedStats();
      let scaledAmt = Math.max(8, Math.round(amount * 0.72));
      if (player.state === 'DODGE' || player.state === 'CROUCH' || label.includes('WARD') || label.includes('BLINK') || label.includes('PARRY') || label.includes('GUARD') || label.includes('AEGIS')) {
        scaledAmt += curStats.evasiveHealBonus;
        if (curStats.evasiveSpiritBonus > 0) this.gainSpirit(curStats.evasiveSpiritBonus);
      }
      return player._advOrig.heal(scaledAmt, label);
    };

    // Wrap Adventure Incoming Damage for Solar Ward Armor Reduction + Cursed Pylon Buff + Aegis Runes Relic!
    player.takeDamage = (amount, attacker, isCrit = false, knockX = 95, knockY = 0) => {
      if (player.isDead || player.isBenched) return;
      const curStats = this.getComputedStats();
      const wasDeflecting = Boolean(player.isDeflecting);
      const cursedMult = attacker && (attacker._cursedBuffTimer || 0) > 0 ? 1.22 : 1.0;
      const aegisRelicDr = this.adventure?.hasRelic?.('orbiting_aegis_runes') ? 0.12 : 0;
      const totalDr = Math.min(0.56, curStats.wardReduction + aegisRelicDr);
      const mitigated = Math.max(1, Math.round(amount * cursedMult * (1 - totalDr)));
      player._advOrig.takeDamage(mitigated, attacker, isCrit, knockX, knockY);
      if (wasDeflecting) {
        this.gainSpirit(18);
      }
      this.syncGaugesToPlayer(player);
    };

    this.syncGaugesToPlayer(player);
  }

  detachFromFighter(player) {
    if (!player || !player._advOrig) return;
    player.maxHp = player._advOrig.maxHp;
    player.hp = Math.min(player.maxHp, player.hp);
    player.gainMana = player._advOrig.gainMana;
    player.gainFinisher = player._advOrig.gainFinisher;
    player.takeDamage = player._advOrig.takeDamage;
    player.heal = player._advOrig.heal;
    delete player._advOrig;
  }

  applyStatsToFighter(player, prevMaxHp = null) {
    if (!player) return;
    const stats = this.getComputedStats();
    const oldMax = prevMaxHp || player.maxHp || stats.maxHp;
    const deltaHp = Math.max(0, stats.maxHp - oldMax);
    player.maxHp = stats.maxHp;
    if (deltaHp > 0 && !player.isDead) {
      player.hp = Math.min(player.maxHp, player.hp + deltaHp);
    } else {
      player.hp = Math.min(player.maxHp, player.hp);
    }
  }

  syncGaugesToPlayer(player) {
    if (!player) return;
    player.mana = Math.max(0, Math.min(player.maxMana || 100, this.ultCharge));
    player.finisherGauge = Math.max(0, Math.min(player.maxFinisherGauge || 100, this.astralCharge));
  }

  gainSpirit(amount) {
    if (!Number.isFinite(amount) || amount === 0) return;
    this.spirit = Math.max(0, Math.min(this.maxSpirit, this.spirit + amount));
  }

  trySpendSkillSpirit() {
    const cost = this.getComputedStats().skillSpiritCost;
    if (this.spirit + 0.01 < cost) return false;
    this.spirit = Math.max(0, this.spirit - cost);
    return true;
  }

  gainAdventureUlt(amount, player = null) {
    if (!Number.isFinite(amount) || amount <= 0) return;
    const stats = this.getComputedStats();
    this.ultCharge = Math.max(0, Math.min(100, this.ultCharge + amount * stats.ultGainMult));
    if (player) this.syncGaugesToPlayer(player);
  }

  gainAstralRelic(rawAmount, player = null, bannerText = '') {
    if (!Number.isFinite(rawAmount) || rawAmount <= 0) return;
    this.astralCharge = Math.max(0, Math.min(100, this.astralCharge + rawAmount));
    if (player) {
      this.syncGaugesToPlayer(player);
      if (bannerText && this.adventure?.game?.vfx) {
        this.adventure.game.vfx.spawnDamageText(
          player.x,
          player.y - 172,
          0,
          true,
          bannerText,
          '#67e8f9'
        );
      }
    }
  }

  gainXp(amount, player = null) {
    if (!Number.isFinite(amount) || amount <= 0 || this.level >= this.maxLevel) return;
    this.xp += Math.round(amount);
    const g = this.adventure?.game;

    let leveledUp = false;
    while (this.xp >= this.xpToNext && this.level < this.maxLevel) {
      this.xp -= this.xpToNext;
      const prevMaxHp = this.getComputedStats().maxHp;
      this.level++;
      leveledUp = true;
      this.skillPoints++;
      this.totalSpEarned++;
      this.xpToNext = Math.round(115 * Math.pow(1.32, this.level - 1));
      this.gainSpirit(35);

      if (player && !player.isDead) {
        this.applyStatsToFighter(player, prevMaxHp);
        if (g?.audio) g.audio.play('holy_hit', player.x);
        if (g?.vfx) {
          g.vfx.spawnShockwave(player.x, player.groundY - 8, 175, '#facc15', 0.45, true);
          g.vfx.spawnBurst(player.x, player.y - 92, 24, '#fde047', 260, { upBias: 145, size: 6 });
          g.vfx.spawnDamageText(
            player.x,
            player.y - 208,
            0,
            true,
            `LEVEL UP! LV.${this.level} (+1 SP)`,
            '#fde047'
          );
        }
      }
    }
    if (leveledUp) {
      this.adventure?.persistHeroProgressIfEnabled?.();
    }
  }

  scaleOutgoingDamage(rawAmount, attacker, monster, _isCrit = false) {
    if (!attacker || attacker.isMonster) return rawAmount;
    const stats = this.getComputedStats();
    const st = attacker.state;
    let mult = stats.atkMult;
    if (st === 'TRUE_ULTIMATE' || rawAmount >= 420) {
      mult = stats.superUltMult;
      if (monster?.isBoss) mult *= 1.18;
    } else if (st === 'ULTIMATE') {
      mult = stats.ultMult;
    } else if (st === 'SKILL' || (rawAmount >= 22 && rawAmount <= 44)) {
      mult = stats.skillMult;
    }

    // Warden / Colossal Boss Guard-Break (+55% DMG) or Exposed Heart-Core (+45% DMG) + Starwood Spore Pod (+25% DMG)
    if ((monster?.staggerBreakTimer || 0) > 0) {
      mult *= 1.55;
    } else if (monster?.isBoss && (monster.vulnerableTimer || 0) > 0) {
      mult *= 1.45;
    }
    if ((monster?._sporeVulnTimer || 0) > 0) {
      mult *= 1.25;
    }
    if (monster?._isAdvCleaveSplash && this.adventure?.hasRelic?.('soul_siphon_cleave')) {
      mult *= 1.20;
    }
    return Math.max(4, Math.round(rawAmount * mult));
  }

  onPlayerHitMonster(player, monster, _dealtDamage) {
    if (!player || player.isDead) return;
    const stats = this.getComputedStats();
    this.comboHits++;
    this.comboTimer = 3.0;

    const st = player.state;
    const relicSpiritBonus = this.adventure?.hasRelic?.('soul_siphon_cleave') ? 4 : 0;
    if (st === 'AUTO_ATTACK' || st === 'IDLE' || st === 'WALK' || st === 'CROUCH' || st === 'JUMP') {
      this.gainSpirit(stats.basicSpiritGain + relicSpiritBonus);
      if (player.skillCooldown > 0 && (this._skillCdShaveThrottle || 0) <= 0) {
        player.skillCooldown = Math.max(0, player.skillCooldown - stats.basicSkillCdShave);
        this._skillCdShaveThrottle = 0.35;
      }
      const comboBonus = this.comboHits >= 8 ? 1.45 : this.comboHits >= 4 ? 1.2 : 1.0;
      const baseUltHit = monster?.isBoss ? stats.bossHitUltGain + 1.5 : 2.1;
      this.gainAdventureUlt(baseUltHit * comboBonus, player);
    } else if (st === 'SKILL') {
      const skillUltHit = monster?.isBoss ? stats.bossHitUltGain + 1.8 : 1.8;
      this.gainAdventureUlt(skillUltHit, player);
    }
  }

  onPlayerCastBasicAttack(player, target, game, opts = {}) {
    if (!player || !game?.vfx) return;
    const stats = this.getComputedStats();
    const rWrath1 = this.getRank('wrath_1');
    const dir = (player.facing || 1) >= 0 ? 1 : -1;
    const isFreeAim = Boolean(this.adventure?.skillSets?.isManualFreeAim?.());

    // Ranged EX Champions (`mage_ex`, `priestess_ex`, `icemage_ex`, `valkyrie_ex`, `archer_ex`):
    // Guarantee full long-range signature projectiles on EVERY basic attack even at Lv.1 (`wrath_1 === 0`)!
    const RANGED_EX_LV1_PROJECTILES = {
      mage_ex: { type: 'fireball', color: '#fb923c', coreColor: '#fef08a', radius: 14, pierce: false, speed: 715 },
      priestess_ex: { type: 'holy_light', color: '#fde047', coreColor: '#ffffff', radius: 14, pierce: true, speed: 725 },
      icemage_ex: { type: 'cryo_shard', color: '#67e8f9', coreColor: '#ffffff', radius: 14, pierce: true, speed: 720 },
      valkyrie_ex: { type: 'dragon_lance', color: '#f43f5e', coreColor: '#fde047', radius: 15, pierce: true, speed: 760 },
      archer_ex: { type: 'arrow', color: '#34d399', coreColor: '#ffffff', radius: 13, pierce: true, speed: 790 }
    };
    const rangedExCfg = RANGED_EX_LV1_PROJECTILES[player.heroId];
    if (rangedExCfg && !opts.heroAlreadySpawnedProjectile) {
      const sx = player.x + dir * 48;
      const sy = (player.y || player.groundY) - 106;
      const speed = rangedExCfg.speed;
      let vx = dir * speed;
      let vy = 0;

      if (
        !isFreeAim &&
        target &&
        !target.isDead &&
        !target.isDummyFocal &&
        (target.x - player.x) * dir > 12
      ) {
        const dx = target.x - sx;
        const ty = target.isColossalBoss
          ? target.y - 135
          : (target.y || target.groundY) - 96;
        const rawDy = ty - sy;
        const absDx = Math.max(90, Math.abs(dx));
        const clampedSlope = Math.max(-0.24, Math.min(0.24, rawDy / absDx));
        const mag = Math.hypot(1, clampedSlope) || 1;
        vx = (dir * speed) / mag;
        vy = (clampedSlope * speed) / mag;
      }

      game.vfx.spawnProjectile({
        x: sx,
        y: sy,
        groundY: player.groundY || player.y,
        vx,
        vy,
        radius: rangedExCfg.radius,
        color: rangedExCfg.color,
        coreColor: rangedExCfg.coreColor,
        owner: player,
        damage: Math.max(48, Math.round((player.attackDamage || 56) * (stats.basicDmgMult || 1))),
        type: rangedExCfg.type,
        pierce: rangedExCfg.pierce,
        maxRange: 680,
        isMeteor: false
      });

      if (!stats.hasHomingSeeker) return;
    }

    // Kaze-Maru (`ronin` & `ronin_ex`): Signature HD-2D Long-Range Crescent Katana Slash Waves (`ronin_slash`) — ZERO blue fireball orbs!
    if (player.heroId === 'ronin' || player.heroId === 'ronin_ex') {
      this.seekerShotCounter++;
      const variant = (((player._autoVariant ?? 0) % 4) + 4) % 4;
      const shouldFireWave =
        rWrath1 >= 2 ||
        this.seekerShotCounter % 2 === 0 ||
        variant === 1 ||
        variant === 3;
      if (!shouldFireWave) return;

      const sx = player.x + dir * 52;
      const sy = (player.y || player.groundY) - 76;
      const speed = 780;
      let vx = dir * speed;
      let vy = 0;

      if (
        !isFreeAim &&
        target &&
        !target.isDead &&
        !target.isDummyFocal &&
        (target.x - player.x) * dir > 12
      ) {
        const dx = target.x - sx;
        const ty = target.isColossalBoss
          ? target.y - 135
          : (target.y || target.groundY) - 76;
        const rawDy = ty - sy;
        const absDx = Math.max(80, Math.abs(dx));
        const clampedSlope = Math.max(-0.22, Math.min(0.22, rawDy / absDx));
        const mag = Math.hypot(1, clampedSlope) || 1;
        vx = (dir * speed) / mag;
        vy = (clampedSlope * speed) / mag;
      }

      const isTwinSlash = rWrath1 >= 2 && this.seekerShotCounter % 2 === 0;
      const waveDamage = rWrath1 >= 2 ? (isTwinSlash ? 66 : 52) : 46;
      game.vfx.spawnProjectile({
        x: sx,
        y: sy,
        groundY: player.groundY || player.y,
        vx,
        vy,
        radius: 18,
        color: '#38bdf8',
        coreColor: '#ffffff',
        owner: player,
        damage: waveDamage,
        type: 'ronin_slash',
        isMeteor: false,
        pierce: true,
        maxRange: 640,
        isTwinSlash,
        ignoreTargets: player._lastAutoMeleeHitFoes || null
      });
      return;
    }

    if (!stats.hasHomingSeeker) return;
    this.seekerShotCounter++;
    if (this.seekerShotCounter % 2 !== 0) return;

    const HERO_SEEKER_CONFIG = {
      warrior: { type: 'blade_wave', color: '#38bdf8', coreColor: '#e0f2fe', radius: 16, pierce: true },
      warrior_ex: { type: 'blade_wave', color: '#38bdf8', coreColor: '#fef08a', radius: 18, pierce: true },
      valkyrie: { type: 'dragon_lance', color: '#f43f5e', coreColor: '#fbbf24', radius: 14, pierce: false },
      valkyrie_ex: { type: 'dragon_lance', color: '#f43f5e', coreColor: '#fde047', radius: 15, pierce: true },
      reaper: { type: 'phantom_scythe', color: '#c084fc', coreColor: '#f43f5e', radius: 16, pierce: true },
      reaper_ex: { type: 'phantom_scythe', color: '#c084fc', coreColor: '#fda4af', radius: 17, pierce: true },
      chronomancer: { type: 'clock_gear', color: '#2dd4bf', coreColor: '#facc15', radius: 14, pierce: false },
      chronomancer_ex: { type: 'clock_gear', color: '#2dd4bf', coreColor: '#fef08a', radius: 15, pierce: true },
      titan: { type: 'forge_wave', color: '#f59e0b', coreColor: '#fef08a', radius: 17, pierce: true },
      titan_ex: { type: 'forge_wave', color: '#f59e0b', coreColor: '#ffffff', radius: 18, pierce: true },
      android: { type: 'cyber_disc', color: '#00f0ff', coreColor: '#ff2e93', radius: 15, pierce: true },
      android_ex: { type: 'cyber_disc', color: '#00f0ff', coreColor: '#facc15', radius: 16, pierce: true },
      icemage: { type: 'cryo_shard', color: '#67e8f9', coreColor: '#ffffff', radius: 13, pierce: false },
      icemage_ex: { type: 'cryo_shard', color: '#67e8f9', coreColor: '#e0f2fe', radius: 14, pierce: true },
      archer: { type: 'arrow', color: '#34d399', coreColor: '#fef08a', radius: 12, pierce: false },
      archer_ex: { type: 'arrow', color: '#34d399', coreColor: '#ffffff', radius: 13, pierce: true },
      priestess: { type: 'holy_light', color: '#facc15', coreColor: '#ffffff', radius: 13, pierce: false },
      priestess_ex: { type: 'holy_light', color: '#fde047', coreColor: '#ffffff', radius: 14, pierce: true },
      ronin: { type: 'ronin_slash', color: '#38bdf8', coreColor: '#ffffff', radius: 18, pierce: true },
      ronin_ex: { type: 'ronin_slash', color: '#38bdf8', coreColor: '#fef08a', radius: 18, pierce: true },
      mage: { type: 'fireball', color: '#fb923c', coreColor: '#fef08a', radius: 12, pierce: false },
      mage_ex: { type: 'fireball', color: '#fb923c', coreColor: '#ffffff', radius: 14, pierce: false },
      nyx_ex: { type: 'nebula_packet', color: '#c084fc', coreColor: '#22d3ee', radius: 14, pierce: true },
      brawler_ex: { type: 'thunderclap_wave', color: '#fbbf24', coreColor: '#ffffff', radius: 18, pierce: true }
    };
    const cfg = HERO_SEEKER_CONFIG[player.heroId] || HERO_SEEKER_CONFIG.mage;
    const isGroundWave =
      cfg.type === 'blade_wave' ||
      cfg.type === 'forge_wave' ||
      cfg.type === 'phantom_scythe' ||
      cfg.type === 'cyber_disc' ||
      cfg.type === 'thunderclap_wave';

    const sx = player.x + dir * 46;
    const sy = (player.y || player.groundY) - (isGroundWave ? 82 : 112);
    const speed = 690;
    let vx = dir * speed;
    let vy = 0;

    if (
      !isFreeAim &&
      target &&
      !target.isDead &&
      !target.isDummyFocal &&
      (target.x - player.x) * dir > 12
    ) {
      const tx = target.x;
      const ty = target.isColossalBoss ? target.y - 135 : (target.y || target.groundY) - (isGroundWave ? 84 : 102);
      const dx = tx - sx;
      const dy = ty - sy;
      const len = Math.hypot(dx, dy) || 1;
      vx = (dx / len) * speed;
      vy = isGroundWave
        ? Math.max(-150, Math.min(150, (dy / len) * speed))
        : (dy / len) * speed - 12;
    }

    game.vfx.spawnProjectile({
      x: sx,
      y: sy,
      groundY: player.groundY || player.y,
      vx,
      vy,
      radius: cfg.radius,
      color: cfg.color,
      coreColor: cfg.coreColor,
      owner: player,
      damage: 58,
      type: cfg.type,
      pierce: cfg.pierce,
      isMeteor: false
    });
  }

  update(dt, player) {
    if (this._skillCdShaveThrottle > 0) {
      this._skillCdShaveThrottle = Math.max(0, this._skillCdShaveThrottle - dt);
    }
    if (this.comboTimer > 0) {
      this.comboTimer = Math.max(0, this.comboTimer - dt);
      if (this.comboTimer <= 0) {
        this.comboHits = 0;
      }
    }
    // Gentle natural Solar Spirit focus regeneration (+5.0/sec)
    if (player && !player.isDead && this.spirit < this.maxSpirit) {
      this.gainSpirit(5.0 * dt);
    }
    if (player) {
      this.syncGaugesToPlayer(player);
    }
  }
}
